import{_ as o,o as a,c as s,a2 as d}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"订阅","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription.md","filePath":"guide/subscription.md","lastUpdated":1792774426000}'),e={name:"guide/subscription.md"};function r(i,t,l,n,h,c){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to &quot;订阅&quot;">​</a></h1><p><strong>订阅</strong> 页管理所有订阅链接。思路和 Sub-Store 一样：<strong>来源 → 处理 → 输出</strong>。每个订阅选一批落地，按需过滤、改名，客户端拿到的格式按 UA 自动识别（也可以复制指定格式的链接）。</p><p>升级前的订阅链接会变成这里的“我的订阅”，链接不变；原来的订阅设置和共享用户也会自动迁移过来。</p><h2 id="订阅与凭据" tabindex="-1">订阅与凭据 <a class="header-anchor" href="#订阅与凭据" aria-label="Permalink to &quot;订阅与凭据&quot;">​</a></h2><p>所有订阅在同一个列表里，靠名称区分（例如“我的手机”“小明”）。</p><ul><li>新建的订阅都有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li>可以设到期日期（到期当天 23:59 后断开）和流量上限，留空就是不限；停用、到期或流量用完后，面板会把它的凭据从节点上删掉</li></ul><p>编辑时“处理”和“链式代理”默认收起（已设置的会展开），标题旁显示已开启的项目。</p><h2 id="导入到客户端" tabindex="-1">导入到客户端 <a class="header-anchor" href="#导入到客户端" aria-label="Permalink to &quot;导入到客户端&quot;">​</a></h2><p>点订阅打开详情，按客户端选择：<strong>点客户端直接唤起 App 导入</strong>，右侧按钮复制该格式的链接。也可以复制上面的通用链接，客户端按 UA 自动拿到对应格式。</p><table tabindex="0"><thead><tr><th>客户端</th><th>格式</th><th>一键导入</th><th>链式代理</th></tr></thead><tbody><tr><td>Clash（Clash Verge、Mihomo Party、FlClash 等）</td><td>Clash / Mihomo 配置</td><td><code>clash://</code></td><td>✓</td></tr><tr><td>sing-box（SFA / SFI / SFM）</td><td>sing-box 配置</td><td><code>sing-box://</code></td><td>✓</td></tr><tr><td>Shadowrocket</td><td>Clash 节点列表</td><td><code>shadowrocket://</code></td><td>✓（每个中转各生成一个“落地（经 中转）”节点）</td></tr><tr><td>Loon</td><td>Loon 节点</td><td><code>loon://</code></td><td>✗</td></tr><tr><td>Quantumult X</td><td>QX 节点</td><td><code>quantumult-x://</code></td><td>✗</td></tr><tr><td>Surge</td><td>Surge 配置</td><td><code>surge://</code></td><td>✓</td></tr><tr><td>Stash</td><td>Stash 配置（Clash 档案，规则集为 YAML）</td><td><code>stash://</code></td><td>✓</td></tr><tr><td>通用</td><td>Base64 分享链接（v2rayN、NekoBox 等）</td><td>仅复制</td><td>✗</td></tr></tbody></table><ul><li>客户端不支持的协议会自动略过，例如 Loon 没有 TUIC，Quantumult X 没有 Hysteria2 / TUIC，Surge 没有 VLESS</li><li>Loon 和 Quantumult X 的节点格式没有前置代理参数，订阅里的落地节点是直连</li><li>指定格式的链接：在订阅链接后加 <code>?format=clash</code>（或 <code>singbox</code>、<code>shadowrocket</code>、<code>loon</code>、<code>qx</code>、<code>surge</code>、<code>stash</code>、<code>base64</code>）</li><li>VLESS 加密（ENC）入站只出现在 Clash / Stash / 通用 base64 输出里（携带完整 <code>encryption</code> 参数），其他格式会略过这类入站</li><li>Snell 入站的下发按客户端区分：Clash / Stash / Shadowrocket 按 v4 口径下发（v4 / v5 入站可下发，v6 入站不下发，客户端不支持 v6）；sing-box 需要 1.14 以上版本、按拉取请求的 UA 判定下发——与是否用 <code>?format=singbox</code> 指定格式无关，用浏览器等普通工具拉取（UA 不带 sing-box 版本）时不含 Snell 属正常现象；Surge 原生支持；Loon、Quantumult X、通用 base64 不下发 Snell</li><li>NaïveProxy 节点在 sing-box 订阅侧需要客户端 1.13 以上版本：按拉取请求的 UA 判定，低于 1.13 时不下发 NaïveProxy 节点、其余节点照常下发（sing-box 出站对 NaïveProxy 的支持自 1.13 起，节点侧链式门同见节点文档）</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ul><li><strong>全部落地</strong>：包括以后新增的落地，不用再回来勾选</li><li><strong>指定落地</strong>：只勾选需要的，分“自建”“导入”和“订阅源”三组。订阅源按整个源勾选，以后更新进来的节点会自动跟上；只要其中一部分可以用下面的过滤</li></ul><p>落地的中转线路会跟着它一起出现在订阅里。</p><h2 id="订阅源" tabindex="-1">订阅源 <a class="header-anchor" href="#订阅源" aria-label="Permalink to &quot;订阅源&quot;">​</a></h2><p>在 <strong>落地 → 订阅源</strong> 添加机场或别人的订阅链接，相当于 Sub-Store 的远程订阅。也可以在 <strong>落地 → 导入</strong> 里粘贴订阅地址，打开 <strong>定时同步</strong>（默认打开）就会存成订阅源；关掉则只导入一次：</p><ul><li>添加后立即拉取一次，节点出现在 <strong>落地</strong> 页“订阅源 · 名称”分组里，可以和其他导入节点一样检测、接中转、放进订阅</li><li><strong>自动更新</strong>：手动 / 6 小时 / 12 小时 / 每天。也可以点卡片右边的按钮立即更新。面板每 10 分钟检查一次到期的订阅源，实际同步时刻最迟可能比设定间隔晚约 10 分钟</li><li>更新时按 <strong>名称</strong> 对上已有节点（名称变了再按地址对）：地址变了就跟着改，挂在上面的中转也会改到新地址；订阅里没有了就删除，但挂着中转的会保留，免得中转断掉</li><li>拉取失败或返回空内容时保留现有节点，卡片上显示错误</li><li>机场返回的流量和到期信息（<code>Subscription-Userinfo</code>）会显示在卡片上</li><li><strong>上传文件</strong>：拿不到订阅链接时，可以给订阅源直接上传订阅文件（Base64、Clash / Mihomo、sing-box 格式均可，上限 5MB）；文件源不自动更新，要更新时在卡片上点「重新上传」</li><li><strong>用途</strong>：订阅源可以标成 <strong>中转</strong> 或 <strong>落地</strong>（默认普通）。新建订阅时会自动带入：标了中转的源整源放进链式代理的中转侧、标了落地的整源作落地；在订阅里随时可改</li><li><strong>新节点设为只通过我的转发访问</strong>：新加进来的节点只用来接中转，不直接进订阅</li><li>删除订阅源时可以选连同节点一起删除，或只删订阅源、节点留下变成普通的导入节点</li></ul><p>典型用法：订阅选“指定落地”，勾上自己的落地和机场订阅源，再用“处理”过滤地区、加国旗、排序，一个链接全搞定。</p><h2 id="处理" tabindex="-1">处理 <a class="header-anchor" href="#处理" aria-label="Permalink to &quot;处理&quot;">​</a></h2><p>按固定顺序执行：<strong>过滤 → 改名 → 国旗 → 去重 → 前缀 → 排序</strong>，最后输出时可以按地区分组。（去重键只含地址/端口/协议，不含名称，所以去重在加前缀之前做不影响结果。）</p><table tabindex="0"><thead><tr><th>步骤</th><th>说明</th></tr></thead><tbody><tr><td>线路</td><td>全部 / 只要中转 / 只要直连</td></tr><tr><td>地区</td><td>只保留选中的地区；“其他”是名称里认不出地区的节点</td></tr><tr><td>协议</td><td>只保留选中的协议</td></tr><tr><td>名称包含 / 排除</td><td>多个关键词用 <code>|</code> 分隔（不区分大小写），或用 <code>/正则/</code></td></tr><tr><td>改名规则</td><td>每行一条 <code>要替换的 =&gt; 替换成</code>，右边留空就是删除，<code>/.../</code> 是正则</td></tr><tr><td>自动加国旗</td><td>按名称识别地区，在前面加国旗；已经有国旗的不重复加</td></tr><tr><td>名称前缀</td><td>给所有节点加同一个前缀</td></tr><tr><td>去重</td><td>地址、端口、协议都相同的只保留第一个</td></tr><tr><td>排序</td><td>面板顺序，或按名称（<code>02</code> 排在 <code>10</code> 前面）</td></tr><tr><td>按地区分组</td><td>Clash / sing-box / Surge 里每个地区一个自动测速组，列在“节点选择”最前面。这是显式开关：开启后即使订阅里只有一个地区，也会生成该地区的分组标题。它与按节点划分的分组标题是两回事——节点分组标题只在入站分布于多个节点分组时才显示</td></tr></tbody></table><p>例如导入的节点叫 <code>花云|香港🇭🇰|1.0x|01</code>，改名规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>花云| =&gt;</span></span>
<span class="line"><span>/\\|[0-9.]+x/ =&gt;</span></span>
<span class="line"><span>| =&gt; -</span></span></code></pre></div><p>会变成 <code>香港🇭🇰-01</code>。编辑时点 <strong>看看结果</strong> 可以先预览，会显示每个节点改名前后的名字和过滤掉了几个。</p><h2 id="链式代理" tabindex="-1">链式代理 <a class="header-anchor" href="#链式代理" aria-label="Permalink to &quot;链式代理&quot;">​</a></h2><p>让客户端先连 <strong>中转节点</strong>，再经它连 <strong>落地节点</strong>，网站看到的是落地节点的 IP。适合“国内 → 香港中转 → 美国落地”这类线路，或者给机场节点套一层自己的落地。</p><p>在订阅的 <strong>链式代理</strong> 里填两个名称表达式（写法同“名称包含”）：</p><ul><li><strong>落地节点</strong>：匹配到的节点挂上中转组，即 Clash / Mihomo 的 <code>dialer-proxy</code>、sing-box 的 <code>detour</code>、Surge 的 <code>underlying-proxy</code></li><li><strong>中转节点</strong>：匹配到的节点放进“中转节点”组</li></ul><p>也可以 <strong>按来源设角色</strong>：在链式代理的「按来源」里，把整个订阅源设成 <strong>不用 / 落地 / 中转</strong>，机场改名、增删节点会自动跟上，不用再逐个对名字；再打开 <strong>自建节点全部作落地</strong>，自己的节点就都走这条链。按来源设了角色后，名称表达式会被忽略（界面有提示）。订阅源标了用途（见上）的话，新建订阅时角色已经自动带好。</p><p>生成的订阅里多两个分组：</p><table tabindex="0"><thead><tr><th>分组</th><th>说明</th></tr></thead><tbody><tr><td>落地节点</td><td>选出口，排在“节点选择”的第一个</td></tr><tr><td>中转节点</td><td>选中转，所有落地节点都经这里选中的节点连接</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">proxies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;美国 落地 01&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vless</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    dialer-proxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;中转节点&quot;</span></span></code></pre></div><ul><li>两项都填且都匹配到节点才生效；同时匹配两项的节点算落地</li><li>注意失效情形：同时匹配两项的节点算落地，所以如果中转表达式唯一能匹配到的节点同时也被落地表达式命中，中转侧就没有可用节点，整条链不会生效——预览和拉取里都不会出现链式分组，目前也不会给出警告。配置时请让中转侧至少保留一个只命中中转表达式的节点</li><li>匹配的是改名后的名字，也认原名；预览里会标出“落地”“中转”</li><li>落地节点仍可在“节点选择”和地区分组里直接选，选中后同样经中转连接；中转节点也可以单独使用</li><li>通用分享链接（Base64）无法表达链式，落地节点在里面是直连</li><li>延迟叠加，速度取决于最慢的一段；落地是 Hysteria2 / TUIC 等 UDP 协议时，中转节点要能转发 UDP</li></ul><blockquote><p>这是客户端侧的链式。想让服务器自己把流量转到另一个节点出去（客户端无感），用入站的 <a href="./nodes#出站">出站</a>。</p></blockquote><h2 id="规则与脚本" tabindex="-1">规则与脚本 <a class="header-anchor" href="#规则与脚本" aria-label="Permalink to &quot;规则与脚本&quot;">​</a></h2><p>订阅编辑页的 <strong>规则与脚本</strong> 区提供两项进阶能力：分流规则引擎和自定义改名脚本。</p><h3 id="分流规则" tabindex="-1">分流规则 <a class="header-anchor" href="#分流规则" aria-label="Permalink to &quot;分流规则&quot;">​</a></h3><p>打开 <strong>分流规则</strong> 开关，并勾选需要的规则分组：</p><table tabindex="0"><thead><tr><th>规则组</th><th>说明</th></tr></thead><tbody><tr><td>广告拦截</td><td>拦截广告域名（REJECT）</td></tr><tr><td>AI 服务</td><td>优先走美国节点</td></tr><tr><td>YouTube / Netflix / 国外媒体</td><td>媒体解锁走代理</td></tr><tr><td>Telegram / Google</td><td>走代理</td></tr><tr><td>微软服务 / 苹果服务 / 游戏平台</td><td>直连</td></tr></tbody></table><p>开启后各客户端的输出变化：</p><table tabindex="0"><thead><tr><th>客户端</th><th>开启规则后的输出</th></tr></thead><tbody><tr><td>Clash / Mihomo</td><td>配置含策略组（<code>proxy-groups</code>）和规则（<code>rules</code>）</td></tr><tr><td>Stash</td><td>配置含策略组和规则（规则集为 YAML 格式，不含 Mihomo 的 DNS / 嗅探设置段）</td></tr><tr><td>sing-box</td><td>配置含路由规则和规则集</td></tr><tr><td>Surge</td><td>配置含自动选择策略组与规则，输出完整配置</td></tr><tr><td>Loon / Quantumult X / Shadowrocket</td><td>输出<strong>完整配置</strong>（含策略组、规则、DNS），而不是纯节点列表</td></tr></tbody></table><p>只开分流规则、没开「按地区分组」时，Clash / sing-box 输出里仍会附带地区分组（规则的落点需要地区组），这是预期行为。</p><blockquote><p>规则分组名会预留，不会和节点重名冲突。规则源来自 MetaCubeX 和 blackmatrix7 的公开规则集，需要节点能访问外网以下载。</p></blockquote><h3 id="自定义脚本" tabindex="-1">自定义脚本 <a class="header-anchor" href="#自定义脚本" aria-label="Permalink to &quot;自定义脚本&quot;">​</a></h3><p>用 JavaScript 给节点批量改名，适合改名规则表达不了的逻辑。</p><ul><li>在 <strong>自定义脚本</strong> 文本框里写 <code>operator(nodes)</code> 函数；脚本里能看到每个节点的 <code>id</code>、<code>name</code>、<code>original</code>（原名）、<code>server</code>、<code>port</code>、<code>protocol</code>、<code>region</code>、<code>line</code>；逐字段层面只有 <code>name</code> 的改动会被采纳，但脚本<strong>返回的数组决定最终的节点集合与顺序</strong>——从数组里去掉的节点会被过滤、调整数组顺序即完成排序</li><li>运行在 goja 沙箱里：无网络、无文件、无定时器；<code>console.log</code> 可用</li><li>单次执行 1 秒超时：死循环脚本会被终止，编辑器会显示错误</li><li>脚本上限 20000 字符，超长会被拒绝</li><li>脚本执行失败不影响改名规则等其他步骤的结果</li></ul><h2 id="独立凭据" tabindex="-1">独立凭据 <a class="header-anchor" href="#独立凭据" aria-label="Permalink to &quot;独立凭据&quot;">​</a></h2><ul><li>每个订阅有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li><strong>停用</strong>、<strong>删除</strong> 或 <strong>到期</strong> 后，面板会把它的凭据从节点上删掉，已导入的配置也连不上了；但共用凭据的节点例外（Shadowsocks、Snell 和导入的节点，见下一条说明）：删除订阅只删链接、共用密码不变，对方已经导入的配置仍能连接</li><li><strong>重置链接和凭据</strong>：旧链接和对方已导入的配置立即失效，适合链接泄露时使用；但共用凭据的节点例外（Shadowsocks、Snell 和导入的节点）：它们用的是共用密码、重置不轮换，重置后对方已经导入的配置仍能连接，要断开只能改对应入站的密码</li><li>支持单独凭据的协议：VLESS、VMess、Trojan、Hysteria2、TUIC、AnyTLS、NaïveProxy。Shadowsocks、Snell 和导入的节点只能共用原来的密码：停用后订阅失效，但对方已经导入的配置仍能连接（界面上会标出“共用凭据”）</li><li>例外：Shadowsocks 2022 入站可以开启「按订阅计量」（见下文同名小节）。开启后订阅新拉取的配置改走独立凭据并计入流量统计与流量上限；开启前已分发的链接照常可用，但不计量</li><li>3 天内到期会推送 <a href="./notify">通知</a></li></ul><h3 id="流量上限" tabindex="-1">流量上限 <a class="header-anchor" href="#流量上限" aria-label="Permalink to &quot;流量上限&quot;">​</a></h3><ul><li>每个订阅单独统计流量（上传 + 下载），可以设 <strong>流量上限</strong>，用完自动断开，和到期一样</li><li><strong>每月重置</strong>：选每月几号，到那天 0 点自动清零；也可以在订阅详情里点 <strong>重置流量</strong> 手动清零，超限断开的会立即恢复</li><li>用到 90% 和用完时会推送 <a href="./notify">通知</a>，概览页的“需要处理”里也会列出</li><li>客户端里能看到已用流量、总量和到期时间（<code>Subscription-Userinfo</code>）</li><li>统计在落地节点上进行：每个订阅走自己的出站，节点用 nftables 计数，Xray 和 sing-box 都支持。需要节点上有 nftables，并且节点 agent 要和面板一起更新到最新版（旧 agent 能正常转发，只是不计数）</li><li>只统计支持单独凭据的协议。共用凭据的落地（Snell、导入的节点，以及未开启「按订阅计量」的 Shadowsocks）分不清是谁在用，不计入</li></ul><h3 id="流量统计" tabindex="-1">流量统计 <a class="header-anchor" href="#流量统计" aria-label="Permalink to &quot;流量统计&quot;">​</a></h3><p>订阅详情里有 <strong>流量统计</strong>：按小时（近 24 小时）、日（近 30 天）、月（近 12 个月）看这条订阅的上传、下载曲线。被分配了这条订阅的用户，在 <strong>我的订阅</strong> 里展开自己的订阅卡片也能看。</p><ul><li>曲线是 <strong>整条订阅的合计</strong>：一条订阅分给多人时，凭据是同一套，流量拆不到个人，每位被分配用户看到的是同一条合计曲线</li><li>统计口径和「已用」一致（只统计独立凭据协议与已开启计量的 Shadowsocks 2022，共用凭据不计入）</li><li>详情与「我的订阅」会标注统计的<strong>起算时间</strong>（订阅创建或上次重置流量之时），显示为「&lt;日期&gt; 起已用 …」；重置流量后起算时间随之更新，起算之前的时段不在统计内</li><li>自 1.3.0 起开始记录，上线之前的时段没有数据</li><li>小时级统计数据保留 400 天，更早的数据会被自动清理</li></ul><h3 id="shadowsocks-按订阅计量" tabindex="-1">Shadowsocks 按订阅计量 <a class="header-anchor" href="#shadowsocks-按订阅计量" aria-label="Permalink to &quot;Shadowsocks 按订阅计量&quot;">​</a></h3><p>Shadowsocks 原本是共用凭据，分不清每条订阅的流量。自建的 Shadowsocks 2022 入站可以在编辑入站时开启「按订阅计量」：</p><ul><li>开启后，面板在<strong>同一节点</strong>上为该入站生成一个计量专用入口（入站列表会显示「计量中」徽标）。订阅<strong>新拉取</strong>的配置自动改走这个入口并使用独立凭据，流量计入该订阅的统计与流量上限，和其他独立凭据协议一样。每个计量入站会在节点上多占一个伴生端口（从节点端口范围中分配，端口被占用时错误信息会点名是计量伴生入站占用）</li><li><strong>已有链接不受影响</strong>：开启前分发的配置继续连原入口、照常可用，但不计量；想纳入计量，让使用者重新拉取一次订阅即可</li><li>订阅停用 / 删除 / 到期 / 超出流量上限后，计量入口上的对应凭据会照常被移除，重新拉取的配置随之断开</li><li>仅支持 2022 系列方法（如 <code>2022-blake3-aes-128-gcm</code>）。传统方法（如 <code>aes-256-gcm</code>）、ShadowTLS 前置的入站、Snell 和导入的节点没有多用户能力，不在覆盖范围内</li><li>带链式出口、已配置分流、仅中转或开启了 PROXY 协议的入站不能开启计量（计量入口是独立直连入口，继承这些设置会把订阅流量静默改道）；已开启计量的入站要改成这些形态，需先关闭计量</li><li>从备份恢复后计量入口会以新凭据重建，此前分发的计量链接随之失效，需重新拉取订阅；手动降级到旧版本前的注意事项见 <a href="./upgrade#降级到旧版本-手动">升级 · 降级到旧版本</a></li><li>注意：持有共用密码的人仍可直连原入口绕过计量与上限（与开启前一致）。要彻底收口，可在大家重新拉取后更换原入站的共用密码——原密码分发的配置会随之失效，计量入口不受影响</li><li>例外：中转端点走原共用凭据、不按订阅计量——经中转（隧道）到达该入站的订阅端点不在计量覆盖内，其流量按隧道口径统计，不计入该订阅的统计与流量上限</li></ul><h2 id="分配给用户与撤销" tabindex="-1">分配给用户与撤销 <a class="header-anchor" href="#分配给用户与撤销" aria-label="Permalink to &quot;分配给用户与撤销&quot;">​</a></h2><p>管理员可以把订阅分配给指定用户（订阅分配），被分配的用户在自己的「我的订阅」里能看到并复制该订阅的链接。</p><p>撤销时注意链接的认凭据方式：<strong>订阅链接认的是订阅本身的 token，不认人</strong>。</p><ul><li>删掉某个用户的分配、禁用或删除该用户：只是让他在面板里看不到这个订阅，<strong>他此前已经复制走的链接仍可继续拉取使用</strong></li><li>要断掉某个人已复制的链接，只能 <strong>重置订阅</strong>（链接和凭据一起轮换，旧链接立即失效）或 <strong>删除订阅</strong>；两者都会同时影响该订阅的全部持有者，无法只断一个人</li><li>停用订阅或订阅到期、流量用完：对全部持有者立即生效，链接拉取直接被拒</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li>点订阅可以导入到客户端、复制各种格式的链接、编辑、重置链接或删除</li><li>所有订阅都包含在 <strong>网站配置 → 数据备份与恢复</strong> 的“内核与入站”里</li><li>订阅当前没有可用节点时（节点全停用、被过滤光或订阅本身为空），拉取返回 HTTP 200 和一份<strong>空节点列表</strong>，而不是错误码——这是刻意的：返回 503 会被客户端当成订阅源故障并保留旧节点，返回空列表能让客户端及时清空</li></ul><h2 id="联邦远端用量的统计口径" tabindex="-1">联邦远端用量的统计口径 <a class="header-anchor" href="#联邦远端用量的统计口径" aria-label="Permalink to &quot;联邦远端用量的统计口径&quot;">​</a></h2><p>把节点通过联邦分享给其他面板使用时，面板记录的远端用量是<strong>提供方节点实际消耗的物理流量</strong>（上传 + 下载的原始字节数），不乘本地隧道的流量倍率（TrafficRatio），也不按本地的配额口径折算。</p><p>因此，远端用量与消费方面板按其倍率、配额算出的计费数字<strong>口径不同、不能直接对账</strong>。不要直接用远端用量数字做本地计费判断；判断某个分享是否超量，以该分享自己设置的流量上限为准（上限同样按物理流量计算）。</p>`,65)])])}const u=o(e,[["render",r]]);export{p as __pageData,u as default};
